function guideLabel(ref){return previewData(ref,'en')?.videoKey?t('说明与视频','Guide & video'):t('阶段说明','Stage guide')}
function pathNode(id,overline,title,description,icon='canopy'){if(state.lang==='zh'){overline=zhText(overline);title=zhText(title);description=zhText(description)}const ref=previewRefForPath(id);return `<div class="path-node"><button class="path-node-select" data-path="${id}" data-stage-ref="${ref||''}"><span class="path-node-icon">${ico(icon,20)}</span><span><small>${overline}</small><strong>${title}</strong>${description?`<span>${description}</span>`:''}</span></button>${ref?stageInfoLink(ref,title).replace('class="stage-node-info"','class="overview-stage-info"').replace('<svg','<span>'+guideLabel(ref)+'</span><svg'):''}</div>`}
function welcome(){return `<section class="pathway-home horizontal-pathway"><h1>${t('进阶路径总览','Progression pathways')}</h1><p class="welcome-intro">${t('室内 IBA 与户外执照路径。点击阶段查看场地与课程；节点内可查看说明和视频。','Indoor IBA and outdoor license pathways. Select a stage for venues and courses; open its guide and video within the node.')}</p><div class="mindmap-toolbar" role="group" aria-label="${t('导图缩放','Map zoom')}"><button data-map-zoom="fit">${t('适应宽度','Fit width')}</button><button data-map-zoom="out" aria-label="${t('缩小导图','Zoom out')}">−</button><span id="map-zoom-label"></span><button data-map-zoom="in" aria-label="${t('放大导图','Zoom in')}">+</button><button data-map-zoom="actual">100%</button></div><div class="mindmap-scroll" tabindex="0" role="region" aria-label="${t('可横向滚动的进阶思维导图','Horizontally scrollable progression mind map')}"><div class="mindmap-canvas"><div class="mindmap-start">${ico('people',25)}<strong>${t('初次体验者','First-time flyer / jumper')}</strong></div><div class="mindmap-tracks"><section class="mindmap-lane"><header>${ico('tunnel',22)}<h2>${t('室内跳伞','Indoor skydiving')}</h2><p>${t('IBA 飞行进阶','IBA Flight Progression')}</p></header><div class="mindmap-chain">${pathNode('indoor-experience',t('初次体验','FIRST FLIGHT'),'Indoor experience',t('体验套餐与地点','Packages & locations'),'tunnel')}${pathNode('iba-1','IBA Level 1','Belly flying',t('腹飞基础控制与移动','Basic control & movement'),'tunnel')}<div class="mindmap-fork indoor-fork"><div class="mindmap-route">${pathNode('iba-2','IBA Level 2','Back flying',t('Static / Dynamic 基础','Static / Dynamic foundation'),'tunnel')}<div class="mindmap-branches">${pathNode('static','IBA Levels 3 · 4 · Pro','Static',t('Head-up / Head-down','Head-up / Head-down'),'tunnel')}${pathNode('dynamic','IBA Levels 3 · 4 · Pro','Dynamic',t('Carving / 动态飞行','Carving & dynamic flight'),'tunnel')}</div></div><div class="formation-route">${pathNode('formation','IBA Levels 2 · 3 · 4','Formation',t('2-way / 3-way / 4-way 编队','2-way / 3-way / 4-way formations'),'people')}</div></div></div><p class="mindmap-note">${t('按分支与技能签注；不换算为户外执照。','Approvals follow IBA tracks and skills; no outdoor license conversion.')} ${src(IBA,'IBA')}</p></section><section class="mindmap-lane"><header>${ico('canopy',22)}<h2>${t('户外跳伞','Outdoor skydiving')}</h2><p>${t('学习 · 执照 · 持证自由跳','Learn · License · Fun jump')}</p></header><div class="mindmap-chain">${pathNode('outdoor-experience',t('初次体验','FIRST JUMP'),'Tandem skydive',t('高度、价格与基地','Altitudes, prices & DZs'))}${pathNode('aff',t('学生','Student'),'AFF / '+t('入门课程','First-jump training'),t('地面课与教练指导','Ground school & instruction'))}${pathNode('pre-a',t('AFF 毕业 · 仍为学生','AFF GRADUATE · STUDENT'),t('A 证进阶','A-license progression'),t('Coach / solo，完成 A 证要求','Coached / solo jumps toward A'))}<div class="mindmap-license-track">${pathNode('a-license','A · 25+ jumps',t('持证自由跳','Fun jump'),t('独立跳伞与基础编队','Independent & formation jumps'))}${pathNode('b-plus','B · 50+ jumps','USPA B license',t('伞控、水训与笔试','Canopy / water training & written exam'))}${pathNode('c-license','C · 200+ jumps','USPA C license',t('经验、技能与笔试','Experience, skills & written exam'))}${pathNode('d-license','D · 500+ jumps','USPA D license',t('进阶技能与笔试','Advanced skills & written exam'))}</div></div><div class="mindmap-specialties"><span>${t('独立分支 · 额外条件','Separate branches · additional prerequisites')}</span>${['balloon','camera','wingsuit','coach','aff','tandem'].map(key=>`<button data-stage-info="m:${key}" data-stage-ref="m:${key}" aria-haspopup="dialog">${txt(milestones[key].name)} <span class="overview-video-label">${guideLabel('m:'+key)}</span><small>${txt(milestones[key].threshold)}</small></button>`).join('')}</div><p class="mindmap-note">${t('前置体验要求依基地而定；完成课程不等于正式取得执照。','Prior-experience requirements vary by DZ; course completion is separate from license issuance.')}</p></section></div></div></div></section>`}

function applyOverviewZoom(){const map=$('.mindmap-canvas'),host=$('.mindmap-scroll');if(!map||!host)return;const fit=Math.min(1,(host.clientWidth-2)/map.offsetWidth);const zoom=state.overviewZoom||fit;map.style.zoom=zoom;$('#map-zoom-label').textContent=Math.round(zoom*100)+'%'}
function dashboard(){
 const names={dz:t('户外基地与价格','Outdoor drop zones & prices'),skills:t('技能训练课程','Skill training courses'),license:t('执照课程','License courses'),tunnel:t('室内场地与课程','Indoor venues & courses')};
 return `<div class="heading"><div><h1 id="dashboard-title">${names[state.view]}</h1></div></div>


 ${filters()}<div class="workspace"><section><div class="result-heading"><h2><span id="result-title">${navs().find(n=>n.id===state.view).name}</span> <span id="result-count" class="count"></span></h2>${state.view==='tunnel'?'':`<span class="sort-caption">${state.origin?t('按预计驾车时间排序','Sorted by estimated driving time'):t('按收录顺序','Listed order')}</span>`}</div><div id="results" aria-live="polite">${results()}</div></section><aside class="aside">${originPanel()}${pathPanel()}<div class="data-info">${ico('book',14)} ${t('每个关键字段旁都保留官网来源。未核实的条件不代表已满足；出发前请联系场地方确认。','Official sources sit beside key fields. Unverified requirements are not a match; contact the venue before visiting.')}</div></aside></div>`;
}
const specialtyGoals=['balloon','camera','wingsuit','teaching'];
function branchOptions(){const labels={all:t('基地指南','Drop zones'),license:t('学习 / 执照','Learn / license'),skills:t('技能训练','Skill training'),fun:t('持证自由跳','Fun jump'),wingsuit:t('翼装','Wingsuit'),camera:t('相机','Camera'),balloon:t('热气球','Balloon'),teaching:t('教练路径','Teaching')};return stageGoalKeys(state.level).map(key=>[key,labels[key]])}
function normalizeOutdoor(){if(!state.role||state.view==='tunnel')return;if(state.level===-1){state.role='tandem';state.view='dz';state.goal='all';return}state.role='sport';if(normalizeStageGoal(state.level,state.goal)!==state.goal){state.goal='all';state.view='dz'};if(state.level===0&&state.view==='skills')state.view='license';if(specialtyGoals.includes(state.goal))state.view='dz'}
function goalButtons(){return branchOptions().filter(([value])=>value!=='all').map(([value,label])=>{const specialty=milestones[value];const button=`<button data-goal="${value}" class="branch-option ${state.goal===value?'active':''}" aria-pressed="${state.goal===value}"><strong>${state.lang==='zh'?zhText(label):label}</strong>${specialty?`<small>${txt(specialty.threshold)}</small>`:''}</button>`;return specialty?`<div class="stage-control branch-control">${button}${stageInfoLink('m:'+value,label)}</div>`:button}).join('')+ratingKeysForStage(state.level).map(key=>`<button class="branch-option rating-guide" data-stage-info="m:${key}" aria-haspopup="dialog"><strong>${txt(milestones[key].name)} <span aria-hidden="true">↗</span></strong><small>${txt(milestones[key].threshold)}</small><span>${guideLabel('m:'+key)}</span></button>`).join('')}

function directionTree(){if(state.level<0)return '';return `<div class="outdoor-direction-tree"><div class="direction-parent"><small>${t('当前阶段','CURRENT STAGE')}</small><strong>${outdoorLabel()}</strong></div><div class="direction-children"><div class="direction-heading"><span>${t('该阶段相关方向','RELATED DIRECTIONS')}</span><button data-goal="all" class="direction-reset ${state.goal==='all'?'active':''}">${t('全部相关','All relevant')}</button></div><div class="direction-options" role="group" aria-label="${t('从当前阶段分出的方向','Directions branching from the current stage')}">${goalButtons()}</div></div></div>`}


function stageInfoLink(ref,label){return `<button class="stage-node-info" data-stage-info="${ref}" aria-haspopup="dialog" aria-label="${t('了解','About')} ${esc(label)}${': '+guideLabel(ref)}" title="${guideLabel(ref)}"><svg width="13" height="13" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 15 15 5M5 5h10v10"/></svg></button>`}
function filters(){if(state.view==='tunnel')return tunnelFilters();const counts=['','', '', '25+', '50+', '200+', '500+'];const labels=[t('体验','Try it'),t('Student / AFF','Student / AFF'),t('AFF 毕业','AFF graduate'),'A','B','C','D'];return `<section class="filters compact-progress" aria-label="${t('户外进阶路径','Outdoor progression path')}"><div class="progress-heading"><strong>${t('户外进阶路径','Outdoor progression')}</strong><span>${t('选择阶段或查看说明','Select a stage or explore its details')}</span></div><div class="progress-spine outdoor-spine" role="group" aria-label="${t('户外经验阶段','Outdoor experience stage')}">${labels.map((name,i)=>`<div class="progress-node"><div class="stage-control"><button data-level="${i-1}" data-stage-ref="o:${i-1}" class="progress-stop ${state.level===i-1?'active':''}" aria-pressed="${state.level===i-1}" aria-label="${esc(outdoorStages()[i])}"><span class="progress-dot"></span><strong>${name}</strong>${counts[i]?`<small>${counts[i]} ${t('跳起','jumps minimum')}</small>`:'<small>&nbsp;</small>'}</button>${stageInfoLink('o:'+(i-1),outdoorStages()[i])}</div></div>`).join('')}</div>${directionTree()}</section>`}
function distance(z){if(!state.origin)return null;const rad=n=>n*Math.PI/180;const [a,b]=state.origin,[c,d]=z.coord;const h=Math.sin(rad(c-a)/2)**2+Math.cos(rad(a))*Math.cos(rad(c))*Math.sin(rad(d-b)/2)**2;return Math.round(6371*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h)))}
function distanceLabel(z){if(state.origin)return `<span class="driving-tag">${esc(routeSummary(state.origin,z,state.lang))}</span>`;return t('设置出发地查看驾车距离与时间','Set origin for driving distance & time')}
function mapLink(z){const url=new URL('https://www.google.com/maps/dir/');url.searchParams.set('api','1');url.searchParams.set('destination',z.address);if(state.origin)url.searchParams.set('origin',state.origin.join(','));return `<a class="map-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer" aria-label="${t('导航到','Navigate to')} ${esc(z.name)}">${ico('pin',15)} ${t('导航','Maps')}</a>`}
function status(z){if(state.role==='tandem')return {kind:'',text:t('双人体验 · 具体年龄、体重与预约条件以官网为准','Tandem · confirm age, weight and reservation requirements')};if(state.level===0)return {kind:'',text:txt(z.learnNote)};if(state.level===1)return {kind:'warn',text:z.id==='svs'?t('本基地 Solo 学生可参与；外来 AFF 学生需先确认','Local Solo students accepted; visiting AFF students must confirm'):t('AFF 毕业仍为学生 · 转入 / 后续训练需先审核','AFF graduates are still students · transfer / progression requires review')};if(z.minimum===null)return {kind:'warn',text:txt(z.eligibility)};if(state.level<z.minimum)return {kind:'blocked',text:txt(z.eligibility)};return {kind:z.id==='svs'?'warn':'',text:txt(z.eligibility)}}
const aircraftReferences={
 caravan:{image:'assets/aircraft/caravan-jump-plane.jpg',title:'Cessna Caravan 208 · Jump modification',source:'https://commons.wikimedia.org/wiki/File:Cessna_Caravan_208_jump-mod.jpg',author:'Peter Ellis',license:'CC BY-SA 3.0',licenseUrl:'https://creativecommons.org/licenses/by-sa/3.0/'},
 kingair:{image:'assets/aircraft/king-air-b200.gif',title:'Beechcraft B200 King Air',source:'https://commons.wikimedia.org/wiki/File:Beechcraft_B200_King_Air_3-view_line_drawing.gif',author:'NASA',license:'Public domain',licenseUrl:'https://www.nasa.gov/nasa-brand-center/images-and-media/'}
};
function plane(z,expanded=false){if(!['bas','cal','svs','mon'].includes(z.id))return `<p class="card-note">${t('机型、载员与爬升数据尚未核实。','Aircraft, capacity and climb data are unverified.')} ${src(z.planeSource||z.source)}</p>`;const calAircraft='https://skydivecalifornia.com/blog/skydiving-altitude-airplanes/',basClimb='https://www.bayareaskydiving.com/tandem',svsFAQ='https://siliconvalleyskydiving.com/FAQ/',pacSpec='https://www.nzaero.com/aircraft/750xl';const ref=z.id==='mon'?aircraftReferences.kingair:z.id==='svs'?{image:'assets/aircraft/pac-750-jump-plane.jpg',title:'PAC 750XL · Skydiving configuration',source:'https://commons.wikimedia.org/wiki/File:Pac_750_skydiving.JPG',author:'Dwight Burdette',license:'CC BY 3.0',licenseUrl:'https://creativecommons.org/licenses/by/3.0/'}:aircraftReferences.caravan;
 const climb=z.id==='mon'?`<div class="climb-row"><strong>8–10 <small>${t('分钟','min')}</small></strong><span>18,000 ft MSL</span></div><div class="climb-row secondary"><strong>6–8 <small>${t('分钟','min')}</small></strong><span>15,000 ft MSL</span></div>`:z.id==='cal'?`<div class="climb-row"><strong>10–13 <small>${t('分钟','min')}</small></strong><span>13,000 ft · Caravan</span></div>`:`<div class="climb-row"><strong>15–20 <small>${t('分钟','min')}</small></strong><span>${t('到出舱高度 · 官网未指定具体高度','To exit altitude · exact altitude unspecified')}</span></div>`;
 const climbSource=z.id==='bas'?basClimb:z.id==='cal'?calAircraft:z.id==='svs'?svsFAQ:S.mon;
 const capacity=z.id==='bas'?t('官网 18 席','18 published seats'):z.id==='cal'?t('Caravan 约 14–18 人','Caravan ≈ 14–18 jumpers'):z.id==='svs'?t('机型最多 17 名跳伞者','Type capacity: up to 17 jumpers'):t('官网 20 / 21 人，口径冲突','Official pages conflict: 20 / 21 jumpers');
 const capacityNote=z.id==='bas'?t('是否含机组未明确；机型参考约 14–18 名跳伞者。','Crew inclusion is unspecified; type examples carry about 14–18 jumpers.'):z.id==='cal'?t('机型参考，非基地确认载员；Cessna 182 参考约 4 人。','Type-based estimates, not confirmed DZ loading; Cessna 182 reference: about 4 jumpers.'):z.id==='svs'?t('制造商机型参数，非基地当日实际载员。','Manufacturer type specification, not the DZ’s actual daily loading.'):t('以基地确认的当前载员为准。','Confirm the current loading with the DZ.');
 const capacitySource=z.id==='bas'?'https://www.bayareaskydiving.com/learn-to-skydive':z.id==='svs'?pacSpec:z.id==='cal'?calAircraft:'https://skydivemontereybay.com/';
 return `<div class="aircraft-structured"><p class="aircraft-model">${txt(z.planeName)}</p><section class="aircraft-climb"><div class="aircraft-label">${ico('skill',17)} ${t('爬升到出舱高度','Climb to exit altitude')}<span>${t('官网资料摘要','Summary of operator information')}</span></div>${climb}<p class="aircraft-rate">${z.id==='cal'?t('官网 Caravan 文章：1,000–1,300 ft/min','Operator’s Caravan article: 1,000–1,300 ft/min'):z.id==='mon'?t('官网称平均爬升率常高于 2,000 ft/min','Operator reports an average climb rate often above 2,000 ft/min'):t('各高度的具体时间与载荷条件需确认','Confirm time at your altitude and load conditions')} ${src(climbSource)}</p></section><section class="aircraft-capacity"><div class="aircraft-label">${ico('people',17)} ${t('能载多少人','Jumper capacity')}</div><strong>${capacity}</strong><p>${capacityNote} ${src(capacitySource)}</p></section><section class="aircraft-appearance"><div class="aircraft-label">${ico('plane',17)} ${t('飞机长什么样','Aircraft appearance')}</div><figure><img src="${ref.image}" alt="${ref.title}" loading="lazy"><figcaption>${z.id==='mon'?t('B200 外观参考图，未展示本基地跳伞舱门改装。','B200 exterior reference; this does not show the DZ’s jump-door modifications.'):z.id==='cal'?t('图为跳伞改装 Caravan，不是 Cessna 182。','Jump-modified Caravan reference, not the Cessna 182.'):t('跳伞改装机型参考照片，非本基地实机。','Jump-configured type reference, not this DZ’s actual airframe.')} ${t('具体舱门、踏板与出舱安排以现场 briefing 为准。','Confirm the actual door, step and exit arrangement in the on-site briefing.')}</figcaption></figure></section><details class="aircraft-sources"><summary>${t('数据依据、口径与图片来源','Data basis, qualifications & image credits')}</summary><dl><dt>${t('爬升数据','Climb data')}</dt><dd>${src(climbSource,t('基地官方页面','Operator page'))} · ${t('官网资料摘要，非逐字引文；时间受载荷、天气与运行安排影响。','Paraphrased operator information, not a quotation; load, weather and operations affect time.')}${z.id==='cal'?` ${t('FAQ 另写约 15 分钟但未绑定机型/高度，此处采用 Caravan 专题文章的对应高度数据。','The FAQ separately states about 15 minutes without a specific type or altitude; the altitude-specific Caravan article is shown here.')} ${src('https://skydivecalifornia.com/tandem-skydiving/faqs/','FAQ')}`:''}</dd><dt>${t('载员依据','Capacity basis')}</dt><dd>${z.id==='bas'||z.id==='cal'?`${t('Caravan 14–18 为其他运营方公开改装案例，不是通用上限或本基地确认值。','Caravan 14–18 comes from other operators’ jump configurations, not a universal limit or confirmed DZ count.')} ${src('https://www.rusol.dk/','RUSOL')}${src('https://startskydiving.com/blog/why-the-type-of-plane-you-jump-from-matters/','Start Skydiving')}${z.id==='cal'?`${t('C182 约 4 名为其他基地公开机型案例。','The C182 four-jumper figure is another operator’s published example.')} ${src('https://skydivemadera.com/experienced-skydivers/','Skydive Madera')}`:''}`:z.id==='svs'?`${src(pacSpec,'NZAero')} · ${t('17 人为制造商跳伞配置参数；基地 FAQ 提到 PAC750XL，当前用机仍需确认。','17 is the manufacturer’s jump-configuration capacity. The DZ FAQ names PAC750XL; confirm the aircraft assigned today.')}`:`${t('基地主页写 21 人，另一篇官网文章的表格写 20 人、正文写 21 人。','The operator homepage lists 21; another official article lists 20 in its table and 21 in its text.')} ${src('https://skydivemontereybay.com/pro-tips/three-reasons-why-skydive-monterey-bay-can-offer-the-worlds-highest-skydive-every-day/')}`}</dd><dt>${t('图片来源','Image credit')}</dt><dd><a href="${ref.source}" target="_blank" rel="noopener noreferrer">${ref.author} · ${ref.title}</a> · <a href="${ref.licenseUrl}" target="_blank" rel="noopener noreferrer">${ref.license}</a> · ${t('原图未改动','Unmodified original')}</dd></dl></details></div>`}
function matchingZones(){let list=zones.filter(z=>matchesRegion(z)&&(!z.documentedAudiences||z.documentedAudiences.includes(state.role==='tandem'?'tandem':'sport')));if(specialtyGoals.includes(state.goal)&&state.view!=='tunnel')return list.filter(z=>courses.some(c=>c.zone===z.id&&c.kind===state.goal&&courseFitsStage(c,state.level)));if(state.role!=='tandem'&&state.goal==='fun'&&state.level<2)list=[];else if(state.goal==='skills'||state.goal==='license')list=list.filter(z=>courses.some(c=>c.zone===z.id&&courseFitsStage(c,state.level)&&(c.kind===state.goal||(state.goal==='license'&&c.id==='canopy'))));else if(state.level===1)list=list.filter(z=>z.affGraduateAccepted);
 if(state.sort==='distance'&&state.origin)list.sort((a,b)=>travelOrder(a)-travelOrder(b));return list}
function results(){let html='',n=0;if(state.view==='tunnel'){const list=indoorVenues.filter(matchesRegion);html=list.map(tunnelCard).join('')||empty(t('当前区域尚未收录室内场地。','No indoor venues documented for this region.'));n=list.length}else if(specialtyGoals.includes(state.goal)){const key=state.goal==='teaching'?(state.level>=5?'tandem':state.level>=4?'aff':'coach'):state.goal;const list=courses.filter(c=>c.kind===state.goal&&courseFitsStage(c,state.level)&&(matchesRegion(zones.find(z=>z.id===c.zone))));if(state.origin)list.sort((a,b)=>travelOrder(zones.find(z=>z.id===a.zone))-travelOrder(zones.find(z=>z.id===b.zone)));n=list.length;html=n?`<div class="info-strip">${t('以下为官网列出的训练方向；参与资格、当前安排与费用需提供方确认。','These training directions are listed by the operators; eligibility, current availability and prices require confirmation.')}</div>`+list.map(courseCard).join(''):empty(t('当前区域尚未收录这一分支的本地课程与开放安排；这不代表没有提供方。','No local courses or current availability for this branch have been documented in this region; this does not establish that no providers exist.'));html+=`<button class="branch-details-button" data-milestone="${key}">${t('查看分支要求与官方资料','View prerequisites and official resources')}</button>`;}else if(state.view==='dz'){
 const list=matchingZones();n=list.length;html=list.map(zoneCard).join('');if(!n)html=empty(t('当前阶段没有匹配项目。未持 A 证请通过学生训练路径查询。','No matching options. Before an A license, use the student training pathway.'));else if(state.role==='sport'&&state.goal==='all'&&state.level===2)html+=`<p class="tiny muted" style="margin:3px 4px">${t('受限基地保留提示，避免将 B-only 误认为 A 证可直接前往。','Restricted DZs remain labeled so B-only access is not mistaken for an A-license match.')}</p>`;
 }else{
 const kind=state.view;let list=courses.filter(c=>(matchesRegion(zones.find(z=>z.id===c.zone)))&&courseFitsStage(c,state.level)&&(c.kind===kind||(kind==='license'&&c.id==='canopy')));if(state.goal==='fun')list=[];if(state.goal==='license')list=list.filter(c=>c.kind==='license'||c.id==='canopy');if(state.goal==='skills')list=list.filter(c=>c.kind==='skills');
 if(state.sort==='distance'&&state.origin)list.sort((a,b)=>travelOrder(zones.find(z=>z.id===a.zone))-travelOrder(zones.find(z=>z.id===b.zone)));n=list.length;html=`<div class="info-strip">${kind==='license'?t('AFF 毕业、完成课程、符合申请条件和正式获得执照是不同阶段。','AFF graduation, course completion, application eligibility and license issuance are distinct stages.'):t('训练方向不等于开放报名；专项先修条件与报价分别核实。','A listed training direction does not confirm enrollment; verify prerequisites and rates separately.')}</div>`+list.map(courseCard).join('');if(!n)html+=empty(t('当前筛选下暂无已整理的相关课程。试试其他目标，或查看 iFLY 风洞训练。','No documented courses match these filters. Try another goal or explore iFLY training.'));
 }queueMicrotask(()=>{const el=$('#result-count');if(el)el.textContent=t(`${n} 个结果`,`${n} results`)});return `<div class="cards">${html}</div>`}
function empty(message){return `<div class="empty">${ico('book',26)}<p style="margin-top:12px">${message}</p></div>`}
function zoneCard(z){const tandem=state.role==='tandem',s=status(z);let service,price,note,height='';
 if(tandem){const options=z.tandemPrices;const h=options[0]?.altitude;service=t('双人体验 / 每人','Tandem / per person');height=altitudeControl(z,true,h);price=options.length?t('全部报价见下表','All rates listed below'):t('查看官网报价','Check official rates');note=txt(z.tandemNote);
 }else if(state.level===0){service=txt(z.learn);price=z.learnPrice?`<span class="price">${money(z.learnPrice,z.currency)}</span><span class="tiny muted">${esc(z.currency)} / ${z.learnUnit?txt(z.learnUnit):t('套餐','package')}</span>`:t('联系询价','Ask for pricing');note=txt(z.learnNote)}
 else if(state.level===1||['skills','license'].includes(state.goal)){let c=courses.find(c=>c.zone===z.id&&courseFitsStage(c,state.level)&&(state.goal==='all'||c.kind===state.goal||(state.goal==='license'&&c.id==='canopy')));service=c?`<button class="course-button" data-course="${c.id}">${txt(c.title)}</button>`:t('学生 / 训练安排待确认','Student / training arrangements unverified');price=c&&c.price?`<span class="price">${money(c.price,c.currency)}</span><span class="tiny muted">${esc(c.currency)} ${txt(c.unit)}</span>`:t('联系询价','Ask for pricing');note=c?txt(c.note):txt(z.learnNote)}
 else{service=t('Fun jump · 跳票 / 租赁套餐','Fun jump · lift / rental package');height=altitudeControl(z,false);price=t('自带 / 租赁 · 见下表','Own / rental · listed below');note=txt(z.note)+' '+txt(z.rentalNote)}
 const serviceSource=tandem?z.tandemSource:state.level===0?z.learnSource:z.source;
 return `<article class="card" id="dz-${z.id}" tabindex="-1" data-zone-card="${z.id}"><div class="card-head"><div><div class="card-title-row"><button class="name-button" data-zone="${z.id}">${esc(z.name)}</button><span class="card-title-actions"><button class="weather-shortcut name-weather" data-weather-zone="${z.id}" aria-label="${esc(z.name)} ${t('当地天气','Local weather')}" title="${t('查看基地天气','View local weather')}">${ico('weather',17)}<span>${t('天气','Weather')}</span></button>${aircraftButton(z)}<button class="contact-trigger name-weather" data-contact="outdoor:${esc(z.id)}" aria-label="${esc(z.name)} ${t('联系方式','Contact options')}" title="${t('查看联系方式','View contact options')}">${ico('people',17)}<span>${t('联系方式','Contact')}</span></button></span></div><div class="location">${ico('pin',13)} ${esc(z.city)}, ${esc(z.subdivision||z.country)} <span>·</span> ${distanceLabel(z)}</div></div>${mapLink(z)}</div><div class="eligibility ${s.kind}">${ico(s.kind?'alert':'check',17)}<span><small class="summary-label">${t('摘要','Summary')}</small>${s.text}${src(tandem?serviceSource:state.level===0?serviceSource:z.eligSource)}</span></div><div class="card-grid"><div><div class="field-label">${t('这次相关的服务','Relevant service')}</div><div class="field-value">${service}</div></div><div><div class="field-label">${t('相关费用','Relevant price')}${src(serviceSource)}</div><div class="field-value">${price}</div></div></div>${height}<p class="card-note">${note}${tandem&&z.tandemStatusSource?' '+src(z.tandemStatusSource,t('运营状态／冲突来源','Status / conflicting source')):''}${z.priceYear<2026&&!tandem&&state.level>=2?` <span class="pill">${t('2023 旧报价','2023 rate table')}</span>`:''}</p>${!tandem?policyExcerpt(z):''}${!tandem&&state.level<2?`<p class="card-note">${t('自带装备能否用于学生训练，需教练单独批准。','Own gear for student training requires instructor approval.')}</p>`:''}<div class="card-foot"><span>${t('核查','Reviewed')} ${esc(z.reviewedAt)}</span></div></article>`;
}
function courseCard(c){const z=zones.find(z=>z.id===c.zone);return `<article class="card"><div class="card-head"><div><button class="course-button" data-course="${c.id}">${txt(c.title)}</button><p class="location">${esc(z.name)} · ${distanceLabel(z)}</p></div>${mapLink(z)}</div><div class="course-meta"><span>${txt(c.tags)}</span></div><div style="margin-top:18px">${c.price?`<span class="price">${money(c.price,c.currency)}</span><span class="small muted">${esc(c.currency)} ${txt(c.unit)}</span>`:`<span class="small">${txt(c.unit)}</span>`} ${src(c.source)}</div><p class="card-note">${txt(c.note)}</p><p class="card-note">${t('自带装备不自动减免套餐价；装备适用性与费用调整需单独确认。','Own gear does not imply a package discount; confirm suitability and pricing adjustments.')}</p><div class="card-foot"><span>${t('项目资格需由提供方确认','Provider must confirm eligibility')}</span><span>${esc(c.reviewedAt)}</span></div></article>`}
const IBA='https://www.tunnelflight.com/skills/';
const ibaLevel=()=>Number(state.ibaLevels[state.ibaTrack]);
const trackName=()=>({static:t('静态飞行','Static'),dynamic:t('动态飞行','Dynamic'),formation:t('编队飞行','Formation')}[state.ibaTrack]);
const ibaName=()=>ibaLevel()===5?t('IBA 专业级','IBA Pro'):t(`IBA ${ibaLevel()} 级`,`IBA Level ${ibaLevel()}`);
function ibaSummary(){const level=ibaLevel(),track=state.ibaTrack;
 if(level===1)return t('Belly flying · 腹飞基础控制、移动与进出风洞','Belly flying · basic control, movement and tunnel entry / exit');
 if(track==='formation')return [null,null,t('2-way · 双人飞行与编队','2-way flying and formations'),t('3-way · 三人编队进阶','3-way formation progression'),t('4-way · 四人编队','4-way formations')][level];
 if(level===2)return t('Back flying · 背飞、移动与姿态转换','Back flying · control, movement and transitions');
 if(track==='static')return level===3?t('Head-up · 坐飞与静态控制','Head-up · sit flying and static control'):level===4?t('Head-down · 倒立飞行与转换','Head-down · control and transitions'):t('Static Pro · 进阶组合与转换','Static Pro · advanced combinations and transitions');
 return level===3?t('Dynamic · 低速 carving 与 layouts','Dynamic · low-speed carving and layouts'):level===4?t('Dynamic · 高速 carving 进阶','Dynamic · high-speed carving progression'):t('Dynamic Pro · 进阶动态组合','Dynamic Pro · advanced dynamic combinations');
}
function indoorLabel(){return state.tunnelMode==='experience'?t('体验者','First-time flyer'):ibaName()}
function tunnelFilters(){const value=state.tunnelMode==='experience'?0:ibaLevel();return `<section class="filters compact-progress indoor-progress" aria-label="${t('室内进阶路径','Indoor progression path')}"><div class="progress-heading"><strong>${t('室内 · IBA 进阶路径','Indoor · IBA progression')}</strong><span>${t('独立于户外执照','Separate from outdoor licenses')}</span></div><div class="indoor-progress-tree"><div class="progress-spine indoor-trunk"><div class="progress-node"><div class="stage-control"><button class="progress-stop ${value===0?'active':''}" data-iba-level="0" data-stage-ref="i:static:0" aria-pressed="${value===0}"><span class="progress-dot"></span><strong>${t('初次体验','First flight')}</strong></button>${stageInfoLink('i:static:0',t('初次体验','First flight'))}</div></div><div class="progress-node"><div class="stage-control"><button class="progress-stop ${value===1?'active':''}" data-iba-level="1" data-stage-ref="i:static:1" aria-pressed="${value===1}"><span class="progress-dot"></span><strong>${t('IBA 1 级','IBA 1')}</strong><small>${t('腹飞','Belly')}</small></button>${stageInfoLink('i:static:1',t('IBA 1 级','IBA 1'))}</div></div></div><div class="indoor-track-rows">${[['static','Static'],['dynamic','Dynamic'],['formation','Formation']].map(([track,label])=>`<div class="indoor-track-row ${state.ibaTrack===track&&value>1?'selected-track':''}"><span class="track-title">${state.lang==='zh'?zhText(label):label}</span><div class="track-stops" role="group" aria-label="${state.lang==='zh'?zhText(label):label} IBA">${(track==='formation'?[2,3,4]:[2,3,4,5]).map(level=>`<div class="track-node stage-control"><button data-iba-branch="${track}" data-branch-level="${level}" data-stage-ref="i:${track}:${level}" class="${state.ibaTrack===track&&value===level?'active':''}" aria-pressed="${state.ibaTrack===track&&value===level}">${level===5?t('专业级','Pro'):t(level+' 级','L'+level)}</button>${stageInfoLink('i:'+track+':'+level,t(zhText(label),label)+' '+(level===5?t('专业级','Pro'):'IBA '+level))}</div>`).join('')}</div></div>`).join('')}</div></div></section>`}
function tunnelPath(){return `<section class="side-panel path-panel"><h3>${t('风洞进阶路径','Tunnel progression pathway')}</h3><div class="path"><div class="step-line"></div><div><strong>${state.tunnelMode==='training'?trackName()+' · '+ibaName():t('初次风洞体验','First-time tunnel flight')}</strong><p>${state.tunnelMode==='training'?ibaSummary():t('先了解体验方式与飞行时间','Explore the experience and flight time')}</p></div></div><div class="path"><div class="step-line"></div><div><strong>${t('教练评估与 IBA 技能签注','Instructor review & IBA skill sign-offs')}</strong><p>${t('风洞等级单独记录，不换算为户外跳伞执照。','Tunnel progression is recorded separately from outdoor skydiving licenses.')}</p></div></div><a class="side-link" href="${IBA}" target="_blank" rel="noopener noreferrer">${t('查看 IBA 技能图谱','View IBA flight skills')}</a></section>`}
function tunnelCard(z){const experience=state.tunnelMode==='experience';return `<article class="card" id="indoor-${esc(z.id)}" tabindex="-1"><div class="card-head"><div><h2>${esc(z.name)}</h2><p class="location">${esc(z.city)} · ${distanceLabel(z)}</p></div>${mapLink(z)}</div><div class="eligibility">${ico('tunnel',18)} ${experience?t('初次风洞体验','First-time flyer experience'):trackName()+' · '+ibaName()}</div>${!experience?`<div class="iba-focus"><div class="field-label">${t('当前练习方向','Current practice focus')}</div><p>${ibaSummary()}</p>${src(IBA,t('IBA 技能来源','IBA skill source'))}</div>`:''}<div class="card-grid"><div><div class="field-label">${t('训练与计费','Format & pricing')}</div><p class="field-value">${experience?t('2 / 4 / 10 flights 体验套餐','2 / 4 / 10-flight packages'):t('Sport flyer 分钟包 / block time','Sport flyer minutes / block time')}</p></div><div><div class="field-label">${t('本地报价','Local pricing')}</div><p class="field-value">${t('联系门店 / 查询预约页','Contact tunnel / check booking')} ${src(z.source)}</p></div></div><p class="card-note">${experience?txt(z.experienceNote):t('此处展示 IBA 练习方向，不代表门店已确认可教授或可预约；分钟包、coach 费、spotting 和具体技能准入请与门店确认。','This is an IBA practice focus, not confirmed local coaching or availability. Ask the tunnel about minutes, coach fees, spotting and skill prerequisites.')}</p><p class="card-note">${esc(z.address)}</p><div class="detail-links" style="margin-bottom:18px"><a href="${experience?z.source:z.sportSource}" target="_blank" rel="noopener noreferrer">${experience?t('官方体验套餐','Official packages'):t('官方 Sport 项目','Official Sport program')}</a><button class="contact-trigger" data-contact="indoor:${esc(z.id)}">${t('联系方式','Contact options')}</button></div><div class="card-foot"><span>${experience?t('体验与进阶训练分别查询','Experience and training are separate'):t('依 IBA 技能签注与门店评估安排','Subject to IBA skill approvals and tunnel review')}</span><span>${esc(z.reviewedAt)}</span></div></article>`}
function setIndoorLevel(value){state.tunnelMode=value===0?'experience':'training';if(value>0)state.ibaLevels[state.ibaTrack]=value}

function liftPrice(z,h){return z.liftPrices.find(r=>r.altitude===h)?.own??null}
function gearPrices(z){return gearPricesHTML(z,state.lang)}
function altitudeControl(z,tandem){if(!tandem)return gearPrices(z);if(!z.tandemPrices.length)return `<p class="card-note">${t('高度与对应报价待补充','Altitudes and paired rates not documented')}</p>`;return `<div class="altitude-list"><table aria-label="${esc(z.name)} ${t('全部高度与价格','all altitudes and prices')}"><thead><tr><th>${t('出舱高度','Exit altitude')}</th><th>${esc(z.currency)} / ${t('人','person')}</th><th>${t('条件','Conditions')}</th></tr></thead><tbody>${z.tandemPrices.map(r=>`<tr><td>${Number.isFinite(r.altitude)?r.altitude.toLocaleString()+' ft'+(z.altitudeReference?' '+esc(z.altitudeReference):''):t('未公布','Not published')}</td><td>${Number.isFinite(r.price)?money(r.price,z.currency):'—'}${Number.isFinite(r.alternatePrice)?' / '+money(r.alternatePrice,z.currency):''}</td><td>${txt(r.condition)}</td></tr>`).join('')}</tbody></table></div>`}
function matchesRegion(z){return state.region==='all'||z.region===state.region}
function regionControls(){if(regions.length<=1)return '';return `<div class="location-region"><p class="field-label">${t('地区','Region')}</p><div class="tags" role="group" aria-label="${t('地区','Region')}">${[{id:'all',name:bi('全部地区','All regions')},...regions].map(r=>`<button class="tag ${state.region===r.id?'active':''}" data-region="${esc(r.id)}" aria-pressed="${state.region===r.id}">${txt(r.name)}</button>`).join('')}</div></div>`}
function originPanel(){return `<section class="side-panel location-panel"><h3>${ico('pin',17)} ${t('地点与路线','Locations & directions')}</h3>${regionControls()}<p class="origin-label">${state.view==='tunnel'?t('前往室内风洞 · 从哪里出发？','Get to the indoor tunnel · starting from?'):t('从哪里出发？','Where are you starting?')}</p><form class="origin-form" id="origin-form"><input id="origin" type="text" value="${esc(state.originText)}" placeholder="${t('城市或出发地址','City or street address')}" aria-label="${t('出发地址','Starting address')}"><button class="submit" type="submit" ${state.searching?'disabled':''}>${state.searching?t('搜索中…','Searching…'):t('搜索','Search')}</button></form><div class="city-shortcuts">${regions.flatMap(r=>r.origins).map(o=>`<button data-city="${esc(o.name)}">${txt(o.label)}</button>`).join('')}${state.origin||state.originCandidates.length||state.searching?`<button data-action="clear-origin">${t('清除','Clear')}</button>`:''}</div><p class="origin-status" role="status">${(state.message&&typeof state.message==='object'?txt(state.message):'')||t('搜索词发送至 Photon；选定候选后才把坐标发给 OSRM 计算驾车路线。快捷城市使用市中心坐标。','Search text goes to Photon; only a selected candidate sends coordinates to OSRM for driving routes. Shortcuts use city-center coordinates.')}</p>${originCandidates()}${drivingOverview()}<div class="mini-map">${mapSvg()}<span class="map-caption">${t('路线估算：OSRM / OpenStreetMap','Route estimates: OSRM / OpenStreetMap')}</span></div></section>`}
