function pathPanel(){return `<section class="side-panel path-panel"><h3>${t('当前选择','Current selection')}</h3><p class="current-path-label">${state.view==='tunnel'?state.tunnelMode==='experience'?t('室内初次体验','First indoor flight'):trackName()+' · '+ibaName():outdoorLabel()}</p><button class="side-link" data-home>${t('查看完整进阶导图','View the full progression map')}</button></section>`}
function openMilestone(key){const m=milestones[key];if(!m)return;const dialog=$('#detail');dialog.innerHTML=`<div class="dialog-top"><div><p class="eyebrow">${t('分支要求','BRANCH PREREQUISITES')}</p><h2>${txt(m.name)}</h2></div><button class="close" aria-label="${t('关闭详情','Close details')}">${ico('close',21)}</button></div><div class="dialog-body">${milestoneHTML(key,state.lang)}</div>`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;dialog.querySelector('.close').onclick=()=>dialog.close();bindContacts()}

function aircraftButton(z){return `<button class="plane-trigger name-weather" data-aircraft="${z.id}" aria-label="${esc(z.name)} ${t('机型详情','Aircraft details')}" title="${txt(z.planeName)||t('机型资料待核实','Aircraft details unverified')}">${ico('plane',17)}<span>${t('机型','Aircraft')}</span></button>`}
function showSimpleDialog(title,body,overline){const dialog=$('#detail');dialog.innerHTML=`<div class="dialog-top"><div><p class="eyebrow" style="margin-bottom:7px">${overline}</p><h2>${title}</h2></div><button class="close" aria-label="${t('关闭详情','Close details')}">${ico('close',21)}</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;dialog.querySelector('.close').onclick=()=>dialog.close();return dialog}
function openWeather(id){const z=zones.find(z=>z.id===id);const dialog=showSimpleDialog(`${ico('weather',22)} ${esc(z.name)}`,weatherSection(z,state.lang),t('基地天气','DROP ZONE WEATHER'));bindWeather(dialog,z,state.lang,{role:state.role,level:state.level,driveDurationSeconds:getRoute(state.origin,z)?.status==='ok'?getRoute(state.origin,z).duration:null},true)}
function openAircraft(id){const z=zones.find(z=>z.id===id);showSimpleDialog(z.name,plane(z,true),t('飞机与载员','AIRCRAFT & CAPACITY'))}
function openDetail(id,type='zone'){
 const dialog=$('#detail');let title,body;if(type==='course'){const c=courses.find(c=>c.id===id),z=zones.find(z=>z.id===c.zone);title=txt(c.title);body=`<p class="detail-address">${esc(z.name)} · ${z.address}</p><p>${txt(c.tags)}</p><h3>${t('费用与包含项','Price & inclusions')}</h3><p>${c.price?`${money(c.price,c.currency)} ${txt(c.unit)}`:txt(c.unit)}</p><p>${txt(c.note)}</p>${c.min===0?videoLink('outdoor-0',state.lang):''}<h3>${t('装备与资格','Gear & eligibility')}</h3><p>${t('课程装备包含项以套餐说明为准；自带装备不自动减免价格，适用性与调整需教练确认。','Course gear inclusions follow package terms. Own gear does not automatically reduce the price; confirm suitability and adjustments with the instructor.')}</p><div class="detail-links">${src(c.source,t('官方课程与报价','Official course & rates'))}${mapLink(z)}<button class="contact-trigger" data-contact="outdoor:${esc(z.id)}">${t('联系方式','Contact options')}</button></div>`}else{const z=zones.find(z=>z.id===id),s=status(z);title=z.name;body=`<p class="detail-address">${z.address} ${src(z.addrSource)}</p><div class="eligibility ${s.kind}">${ico(s.kind?'alert':'check',17)}<span>${s.text}${src(z.eligSource)}</span></div>`;
 if(state.role==='tandem')body+=`<h3>${t('出舱高度与每人费用','Exit altitudes & per-person rates')}</h3>${altitudeControl(z,true)}<p>${txt(z.tandemNote)} ${src(z.tandemSource)}</p>`;
 else{body+=`<h3>${t('当前阶段相关服务','Services for your current stage')}</h3>${state.level===0?`<p>${txt(z.learn)} · ${z.learnPrice?money(z.learnPrice,z.currency):t('询价','Ask for pricing')}</p><p>${txt(z.learnNote)} ${src(z.learnSource)}</p>`:state.level===1?`<p>${t('尚未取得 A 证，请与基地核实学生转入、记录审核和 coach / solo 安排。不能按持证 Fun jump 资格前往。','Without an A license, confirm student transfer, records review and coached / solo arrangements. Licensed fun-jump access does not apply.')}</p>`:`<p>${txt(z.eligibility)} ${src(z.eligSource)}</p>${gearPrices(z)}<p>${txt(z.note)} ${txt(z.rentalNote)} ${src(z.source)}</p>`}`;const list=courses.filter(c=>c.zone===z.id&&courseFitsStage(c,state.level)&&(state.goal==='all'||c.kind===state.goal||(state.goal==='license'&&c.id==='canopy')));if(list.length)body+=`<h3>${t('匹配的课程与训练','Matching courses & training')}</h3>${list.map(c=>`<p><button class="course-button" data-course="${c.id}">${txt(c.title)}</button> · ${c.price?'USD '+c.price.toLocaleString()+' '+txt(c.unit):txt(c.unit)}</p>`).join('')}`;}
 body+=policyExcerpt(z);body+=`<details class="detail-section"><summary>${t('飞机信息与载员依据','Aircraft & capacity sources')}</summary>${plane(z,true)}</details><div class="detail-links">${mapLink(z)}<button class="contact-trigger" data-contact="outdoor:${esc(z.id)}">${t('联系方式','Contact options')}</button>${src(z.addrSource,t('官方地点说明','Official location details'))}</div>`;}
 dialog.innerHTML=`<div class="dialog-top"><div><p class="eyebrow" style="margin-bottom:7px">${state.role==='tandem'?t('双人跳伞','TANDEM'):stageNames()[state.level]}</p><h2>${title}</h2></div><button class="close" aria-label="${t('关闭详情','Close details')}">${ico('close',21)}</button></div><div class="dialog-body">${body}<p class="tiny muted" style="margin-top:23px">${t('核查：2026.11.21 · 静态官网资料，不代表实时可预约。','Reviewed Nov 21, 2026 · Static official information; availability not confirmed.')}</p></div>`;
 if(!dialog.open)dialog.showModal();dialog.scrollTop=0;dialog.querySelector('.close').onclick=()=>dialog.close();dialog.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>openDetail(b.dataset.course,'course'));bindContacts();
}
function openStageDetails(ref){const data=previewData(ref,state.lang);if(!data)return;const dialog=showSimpleDialog(data.title,stageDetailsHTML(ref,state.lang),data.videoKey?t('项目说明与视频','GUIDE & VIDEO'):t('阶段说明','STAGE GUIDE'));dialog.querySelector('[data-demo-play]')?.addEventListener('click',e=>{const button=e.currentTarget,iframe=document.createElement('iframe');const params=new URLSearchParams({autoplay:'1',rel:'0'});if(Number(button.dataset.demoStart)>0)params.set('start',button.dataset.demoStart);if(Number(button.dataset.demoEnd)>0)params.set('end',button.dataset.demoEnd);iframe.src='https://www.youtube-nocookie.com/embed/'+button.dataset.demoPlay+'?'+params;iframe.title=button.getAttribute('aria-label');iframe.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';iframe.allowFullscreen=true;dialog.querySelector('[data-demo-media]').replaceChildren(iframe)});dialog.querySelectorAll('[data-milestone]').forEach(button=>button.onclick=()=>openStageDetails('m:'+button.dataset.milestone))}
function bind(){
 bindContacts();
 const refresh=$('[data-refresh-routes]');if(refresh)refresh.onclick=()=>{if(!state.origin)return;const origin=[...state.origin],key=origin.join(',');const request=ensureRoutes(origin,[...zones,...indoorVenues],{force:true});render();request.then(()=>{if(state.origin?.join(',')===key)render()})};
 document.querySelectorAll('[data-stage-info]').forEach(button=>button.onclick=()=>openStageDetails(button.dataset.stageInfo));

 document.querySelectorAll('[data-map-zoom]').forEach(b=>b.onclick=()=>{const action=b.dataset.mapZoom;const current=parseInt($('#map-zoom-label').textContent)/100;state.overviewZoom=action==='fit'?null:action==='actual'?1:Math.max(.2,Math.min(1.5,current+(action==='in'?.15:-.15)));applyOverviewZoom();remember()});

 document.querySelectorAll('[data-path]').forEach(button=>button.onclick=()=>{const path=button.dataset.path;state.goal='all';state.region='all';if(path==='indoor-experience'||path==='outdoor-experience'){state.role='tandem';if(path==='indoor-experience')state.tunnelMode='experience';else state.level=-1;state.view=path==='indoor-experience'?'tunnel':'dz'}else{state.role='sport';if(['iba-1','iba-2','static','dynamic','formation'].includes(path)){state.view='tunnel';state.tunnelMode='training';state.ibaTrack=['dynamic','formation'].includes(path)?path:'static';state.ibaLevels[state.ibaTrack]=path==='iba-1'?1:path==='iba-2'?2:path==='formation'?2:3}else{state.level={aff:0,'pre-a':1,'a-license':2,'b-target':2,'b-plus':3,'c-license':4,'d-license':5}[path];state.view=['aff','pre-a','b-target'].includes(path)?'license':'dz';if(['aff','pre-a','b-target'].includes(path))state.goal='license'}}state.outdoorView=state.view==='tunnel'?'dz':state.view;render();window.scrollTo({top:0,behavior:'instant'})});
 document.querySelectorAll('[data-map-zone]').forEach(link=>link.onclick=e=>{e.preventDefault();const id=link.dataset.mapZone;if(!id.startsWith('indoor-')&&state.view!=='dz'){state.view='dz';render()}const target=$('#'+(id.startsWith('indoor-')?id:'dz-'+id));if(!target)return;target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});target.focus({preventScroll:true});target.classList.add('map-target');setTimeout(()=>target.classList.remove('map-target'),1800)});

 document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>{state.role=null;state.view='dz';render()});
 document.querySelectorAll('[data-discipline]').forEach(b=>b.onclick=()=>{if(b.dataset.discipline==='indoor'){if(state.role&&state.view!=='tunnel')state.outdoorView=state.view;state.role=state.level===-1?'tandem':'sport';state.view='tunnel'}else{state.role=state.level===-1?'tandem':'sport';state.view=state.outdoorView||'dz'}render();window.scrollTo({top:0,behavior:'instant'})});
 document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{state.region=b.dataset.region;render()});

 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(state.role==='sport'&&state.level===0&&b.dataset.view==='skills')return;state.view=b.dataset.view;render()});
 document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{state.level=Number(b.dataset.level);state.role=state.level===-1?'tandem':'sport';render()});

 document.querySelectorAll('[data-goal]').forEach(b=>b.onclick=()=>{if(!branchOptions().some(([key])=>key===b.dataset.goal))return;state.goal=b.dataset.goal;state.view=['license','skills'].includes(state.goal)?state.goal:'dz';render()});
 document.querySelectorAll('[data-milestone]').forEach(b=>b.onclick=()=>openMilestone(b.dataset.milestone));
 document.querySelectorAll('[data-iba-branch]').forEach(b=>b.onclick=()=>{state.ibaTrack=b.dataset.ibaBranch;setIndoorLevel(Number(b.dataset.branchLevel));render()});
 document.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>openDetail(b.dataset.zone));
 document.querySelectorAll('[data-weather-zone]').forEach(b=>b.onclick=()=>openWeather(b.dataset.weatherZone));
 document.querySelectorAll('[data-aircraft]').forEach(b=>b.onclick=()=>openAircraft(b.dataset.aircraft));
 document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>openDetail(b.dataset.course,'course'));

 document.querySelectorAll('[data-tunnel-mode]').forEach(b=>b.onclick=()=>{state.tunnelMode=b.dataset.tunnelMode;render()});
 document.querySelectorAll('[data-iba-track]').forEach(b=>b.onclick=()=>{state.ibaTrack=b.dataset.ibaTrack;render()});
 document.querySelectorAll('[data-iba-level]').forEach(b=>b.onclick=()=>{setIndoorLevel(Number(b.dataset.ibaLevel));render()});

 document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>lookup(b.dataset.city,{shortcut:true}));
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.action;if(a==='language'){state.lang=state.lang==='zh'?'en':'zh';state.languageChosen=true;}if(a==='switch')state.role=null;if(a==='clear-origin'){++querySequence;state.origin=null;state.originConfirmed=false;state.originText='';state.originCandidates=[];state.searching=false;state.message=''}render()});

 document.querySelectorAll('[data-origin-candidate]').forEach(button=>button.onclick=()=>{const candidate=state.originCandidates[Number(button.dataset.originCandidate)];if(candidate)selectOrigin(candidate)});
 const form=$('#origin-form');if(form)form.onsubmit=e=>{e.preventDefault();lookup($('#origin').value)};
}
let querySequence=0;
async function lookup(value,{shortcut=false}={}){
 const raw=value.trim();if(!raw||(state.searching&&!shortcut))return;const seq=++querySequence;
 if(shortcut){const origin=regions.flatMap(r=>r.origins).find(o=>o.name===raw);if(origin){selectOrigin({coord:origin.coord,label:origin.name});return}}
 state.originText=raw;state.origin=null;state.originConfirmed=false;state.originCandidates=[];state.searching=true;state.message=bi('正在搜索候选地点…','Searching for matching places…');render();
 try{
  const venues=[...zones,...indoorVenues].filter(z=>state.region==='all'||z.region===state.region);
  const focus=venues.length?[venues.reduce((sum,z)=>sum+z.coord[0],0)/venues.length,venues.reduce((sum,z)=>sum+z.coord[1],0)/venues.length]:null;
  const candidates=await searchCandidates(raw,{focus,endpoint:geocodingEndpoint});if(seq!==querySequence)return;
  state.originCandidates=candidates;state.message=candidates.length?bi('请选择正确地点；确认后才计算驾车路线。','Choose the correct place. Driving routes start only after selection.'):bi('没有找到候选，请补充城市、州／省或国家后重试。','No matches found. Add a city, state/province or country and search again.');
 }catch{if(seq!==querySequence)return;state.message=bi('地址搜索暂不可用，请重试或使用城市快捷项。','Place search is unavailable. Retry or choose a city shortcut.')}
 if(seq!==querySequence)return;state.searching=false;render();
}
function selectOrigin(candidate){++querySequence;state.searching=false;state.origin=candidate.coord;state.originConfirmed=true;state.originText=candidate.label;state.originCandidates=[];state.message=bi('已选定：'+candidate.label+'。驾车估算不含实时交通。','Selected: '+candidate.label+'. Driving estimates exclude live traffic.');render()}
function originCandidates(){if(!state.originCandidates.length)return '';return `<section class="origin-candidates" aria-label="${t('候选地点','Candidate locations')}"><h4>${t('请选择地点','Choose a location')}</h4><p>${t('请核对城市、州／省和国家。结果会偏向当前收录区域，但不会自动选定。','Check the city, state/province and country. Results favor the current region; none is selected automatically.')}</p>${state.originCandidates.map((candidate,i)=>`<button type="button" data-origin-candidate="${i}"><strong>${esc(candidate.title)}</strong><span>${esc(candidate.label)}</span><small>${candidate.coord.map(n=>n.toFixed(4)).join(', ')}</small></button>`).join('')}<small class="candidate-source"><a href="https://photon.komoot.io/" target="_blank" rel="noopener noreferrer">Photon</a> / <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">© OpenStreetMap contributors</a></small></section>`}

window.addEventListener('resize',applyOverviewZoom);
$('#detail').addEventListener('close',()=>$('#detail').querySelectorAll('iframe').forEach(frame=>frame.remove()));
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
render();

function travelOrder(z){return getRoute(state.origin,z)?.duration??Infinity}
function mountLocationMap(){
 const host=$('#venue-map');if(!host)return;
 const locations=state.view==='tunnel'?indoorVenues.filter(matchesRegion):matchingZones();
 mountVenueMap(host,{locations,origin:state.origin,originText:state.originText,lang:state.lang,indoor:state.view==='tunnel',onSelect:id=>{const target=document.getElementById((state.view==='tunnel'?'indoor-':'dz-')+id);if(!target)return;target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});target.focus({preventScroll:true});target.classList.add('map-target');setTimeout(()=>target.classList.remove('map-target'),1800)}});
 if(state.origin){const originKey=state.origin.join(',');ensureRoutes(state.origin,[...zones,...indoorVenues]).then(changed=>{if(changed&&state.origin?.join(',')===originKey&&document.getElementById('venue-map'))render()})}
}

function bindContacts(){document.querySelectorAll('[data-contact]').forEach(button=>button.onclick=()=>openContacts(button.dataset.contact))}
function openContacts(ref){
 const [kind,id]=ref.split(':');const z=(kind==='indoor'?indoorVenues:zones).find(v=>v.id===id);if(!z)return;
 const dialog=$('#detail');
 dialog.innerHTML=`<div class="dialog-top"><div><p class="eyebrow">${t('联系方式','CONTACT OPTIONS')}</p><h2>${esc(z.name)}</h2></div><button class="close" aria-label="${t('关闭详情','Close details')}">${ico('close',21)}</button></div><div class="dialog-body contact-options"><section class="contact-option"><h3>${t('电话','Phone')}</h3><p>${esc(z.phone||t('未收录','Not documented'))}</p>${z.phone?`<div class="contact-actions"><button data-copy-phone>${t('复制号码','Copy number')}</button><a href="tel:${esc(z.phone)}">${t('拨打电话','Dial number')}</a></div>`:''}</section>${z.email?`<section class="contact-option"><h3>${t('邮箱','Email')}</h3><p>${esc(z.email)}</p><div class="contact-actions"><a href="mailto:${esc(z.email)}">${t('撰写邮件','Compose email')}</a></div></section>`:''}<section class="contact-option"><h3>${t('官方网站','Official website')}</h3><p>${esc(z.source)}</p><div class="contact-actions"><a href="${esc(z.source)}" target="_blank" rel="noopener noreferrer">${t('打开官网','Open website')}</a></div></section><section class="contact-option"><h3>${t('地址','Address')}</h3><p>${esc(z.address)}</p>${mapLink(z)}</section></div>`;
 if(!dialog.open)dialog.showModal();dialog.scrollTop=0;dialog.querySelector('.close').onclick=()=>dialog.close();
 const copy=dialog.querySelector('[data-copy-phone]');if(copy)copy.onclick=async()=>{try{await navigator.clipboard.writeText(z.phone);copy.textContent=t('已复制','Copied')}catch{copy.textContent=t('请选中上方号码复制','Select the number above to copy')}};
}

function drivingOverview(){
 if(!state.origin)return '';
 const locations=(state.view==='tunnel'?indoorVenues.filter(matchesRegion):matchingZones()).slice().sort((a,b)=>travelOrder(a)-travelOrder(b));
 const loaded=locations.filter(z=>getRoute(state.origin,z)?.status==='ok').length;
 const loading=locations.some(z=>!getRoute(state.origin,z)||getRoute(state.origin,z)?.status==='loading');
 return `<section class="driving-overview" aria-label="${t('各场地驾车时间与距离','Driving time and distance by venue')}" aria-live="polite"><div class="driving-overview-heading"><strong>${t('驾车时间与距离','Driving time & distance')}</strong><button data-refresh-routes ${loading?'disabled':''}>${loading?t('计算中…','Calculating…'):t('重新计算','Refresh')}</button></div><p>${t('按预计驾车时间排序 · 不含实时路况','Sorted by estimated driving time · no live traffic')}</p><div class="driving-overview-rows">${locations.map(z=>`<button class="driving-overview-row" data-map-zone="${state.view==='tunnel'?'indoor-':''}${esc(z.id)}"><span>${esc(z.name)}</span><strong>${esc(routeSummary(state.origin,z,state.lang))}</strong></button>`).join('')}</div>${!loading&&loaded<locations.length?`<p class="driving-unavailable">${t('部分路线暂不可用，可重新计算或打开场地导航；不会用直线距离代替。','Some routes are unavailable. Retry or open venue Maps; straight-line distance is not substituted.')}</p>`:''}<small>OSRM / OpenStreetMap · ${t('从已选出发地计算的驾车路线','Driving routes from the selected origin')}</small></section>`;
}
